{"code":"import pandas as pd, statsmodels.formula.api as smf
x=pd.read_csv('data/explore.csv')
cols=['nitrogen_ppm','phosphorus_ppm','potassium_ppm','soil_ph','irrigation_mm','seed_density','mulch_depth_cm','biochar_g','fungicide_ml','shade_pct']
for c in cols:
 d=x[['yield_kg','farm',c]].dropna(); m=smf.ols(f'yield_kg ~ {c} + C(farm)',d).fit()
 print(c, round(m.params[c],4), round(m.pvalues[c],5), round(m.rsquared,3))"}

{"code":"import pandas as pd, statsmodels.formula.api as smf
x=pd.read_csv('data/explore.csv')
cs=[c for c in x.columns if c not in ['id','farm','yield_kg']]
for c in cs:
 d=x.dropna(subset=['yield_kg',c]); m=smf.ols(f'yield_kg ~ {c}*C(farm)',d).fit()
 print(c, 'slope', round(m.params[c],3),'interaction p',round(m.f_test([z for z in m.params.index if ':' in z]).pvalue,4))"}
